$js = <<<'JS'
(()=>{function boot(){document.querySelectorAll('.zo-game-root--pocket-creature-merge').forEach(game=>{if(game.dataset.ready)return;game.dataset.ready='1';const all=JSON.parse(game.dataset.labels),t=all[game.dataset.lang]||all.tr;const $=s=>game.querySelector(s),status=$('.status'),scoreEl=$('.score');let score=0,ended=false;const say=s=>status.textContent=s;function points(n){score=n;scoreEl.textContent=n;}
const board=$('.board');board.style.gridTemplateColumns='repeat(4,1fr)';let a=[],running=false;const colors=['#bee8da','#91ddd3','#65ccbd','#ffd77b','#ffb574','#ff9287','#d8a4fa'];
function draw(){board.replaceChildren();a.forEach(v=>{const d=document.createElement('div');d.className='cell tile';if(v){d.style.setProperty('--tile',colors[Math.min(6,Math.log2(v)-1)]);const eyes=document.createElement('span');eyes.className='eyes';eyes.textContent='● ●';const number=document.createElement('span');number.textContent=v;d.append(eyes,number);}board.append(d);});}
function spawn(){const free=a.map((v,i)=>v? -1:i).filter(i=>i>=0);if(free.length)a[free[Math.floor(Math.random()*free.length)]]=Math.random()<.9?2:4;}
function reset(){a=Array(16).fill(0);points(0);ended=false;running=true;spawn();spawn();draw();say(t.instructions);}
function move(dir){if(!running||ended)return;const old=a.join(',');for(let line=0;line<4;line++){const ids=Array.from({length:4},(_,k)=>dir==='left'?line*4+k:dir==='right'?line*4+3-k:dir==='up'?k*4+line:(3-k)*4+line);const v=ids.map(i=>a[i]).filter(Boolean),out=[];for(let k=0;k<v.length;k++){if(v[k]===v[k+1]){out.push(v[k]*2);points(score+v[k]*2);k++;}else out.push(v[k]);}ids.forEach((i,k)=>a[i]=out[k]||0);}if(a.join(',')===old)return;spawn();draw();if(a.includes(128)){ended=true;say(t.win);}else if(a.every(Boolean)&&!a.some((v,i)=>(i%4<3&&v===a[i+1])||(i<12&&v===a[i+4]))){ended=true;say(t.over);}}
game.querySelectorAll('[data-dir]').forEach(b=>b.addEventListener('click',()=>move(b.dataset.dir)));game.addEventListener('keydown',e=>{const dir={ArrowLeft:'left',ArrowRight:'right',ArrowUp:'up',ArrowDown:'down'}[e.key];if(dir){e.preventDefault();move(dir);}});let touch=null;board.style.touchAction='none';board.addEventListener('pointerdown',e=>{touch=[e.clientX,e.clientY];board.setPointerCapture(e.pointerId);});board.addEventListener('pointerup',e=>{if(!touch)return;const dx=e.clientX-touch[0],dy=e.clientY-touch[1];touch=null;if(Math.max(Math.abs(dx),Math.abs(dy))>20)move(Math.abs(dx)>Math.abs(dy)?(dx>0?'right':'left'):(dy>0?'down':'up'));});board.addEventListener('pointercancel',()=>touch=null);$('.start').addEventListener('click',reset);reset();
 });}if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot);else boot();})();
JS;
